[[ ## document ## ]]
{
  "title": "Cardinal Ridge Builders – 1120-S PBC Request",
  "path": "Cardinal_Ridge_Builders/PBC_Request_1120S.docx",
  "document": {
    "blocks": [
      {
        "kind": "heading",
        "level": 1,
        "text": "PBC Request – Cardinal Ridge Builders, Inc. (1120-S Setup)"
      },
      {
        "kind": "paragraph",
        "text": "Engagement: FY2024 S Corporation Income Tax Return (Form 1120-S)\nPrepared by: Desmond Ortiz, Senior Accountant, Tax\nDate issued: [Current Date]"
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "General Corporate Items"
      },
      {
        "kind": "list",
        "ordered": false,
        "items": [
          "Copy of the entity's Articles of Incorporation and any amendments (including S-election documentation, Form 2553).",
          "Copy of the most recent issued financial statements (balance sheet, income statement, cash flow) for the fiscal year ended December 31, 2024.",
          "Copy of the prior year's tax return (Form 1120-S) and all supporting schedules.",
          "Federal and state estimated tax payment records (including dates and amounts paid)."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Books & Records"
      },
      {
        "kind": "list",
        "ordered": false,
        "items": [
          "Trial balance (beginning and ending) with supporting detail for all general ledger accounts.",
          "General ledger detail for all revenue and expense accounts for the full year.",
          "Bank statements (all accounts) and reconciliations for all 12 months of 2024.",
          "Credit card statements and supporting expense detail for all company cards.",
          "Loan statements and amortization schedules for all outstanding debt."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Revenue & Contracts"
      },
      {
        "kind": "list",
        "ordered": false,
        "items": [
          "Customer detail (name, address, EIN/SSN) for all contracts or jobs active during 2024.",
          "Copies of all executed construction contracts (or a listing showing contract value, completion %, and retainage).",
          "Progress billings and job cost detail by project (costs-to-date, revenue recognized, over/under billings).",
          "1099-NEC forms issued to subcontractors and vendors (amounts $600 or more).",
          "Listing of all subcontractor labor costs by job, with supporting invoices."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Expenses & Fixed Assets"
      },
      {
        "kind": "list",
        "ordered": false,
        "items": [
          "Fixed asset schedule: additions, disposals, depreciation detail (including date placed in service and cost).",
          "Receipts or invoices for any fixed asset purchases during 2024 (vehicles, equipment, real estate).",
          "Vehicle registration and usage logs (for vehicles used in the business).",
          "Detail of all repairs and maintenance expenses exceeding $2,500 per invoice.",
          "Business meals and entertainment expense detail (who, when, where, business purpose).",
          "Home office expense calculation, if any owner claims or the company reimburses home-office use.",
          "Insurance policies and premium statements (general liability, workers' comp, health, auto)."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Payroll & Shareholder Items"
      },
      {
        "kind": "list",
        "ordered": false,
        "items": [
          "Payroll summaries by employee (gross wages, federal/state withholdings, FICA, unemployment).",
          "Copies of all W-2s issued for 2024 and W-3 transmittal.",
          "Quarterly 941s and state unemployment filings (UI-3 or equivalent).",
          "Shareholder names, addresses, and SSNs, plus ownership percentages for all shareholders as of year-end.",
          "Shareholder distributions (amounts, dates, and form — cash or property).",
          "Shareholder loans to or from the company (opening balance, additions, repayments, interest).",
          "Schedules K-1 for the prior year, to confirm shareholder basis carryforward."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Other Tax Items"
      },
      {
        "kind": "list",
        "ordered": false,
        "items": [
          "Sales/use tax returns and payments (state and local) for 2024.",
          "Personal property tax returns (if filed) and assessed values.",
          "Any notices received from federal or state tax authorities during 2024.",
          "Documentation for any related-party transactions (including with owners or their other entities).",
          "Schedule of any bad debt write-offs (customer name, amount, collection efforts).",
          "NOL, capital loss, or charitable contribution carryforward schedules from prior years.",
          "Copy of the prior year's shareholder basis schedules (if maintained)."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Notes & Deadlines"
      },
      {
        "kind": "paragraph",
        "text": "Please provide all items via the secure client portal (Box link) or to my email at des.ortiz@firm.com. If any item is not applicable or unavailable, please note that in your response rather than leaving it blank. I will need these materials no later than [Due Date – e.g., March 15, 2025] to meet the filing deadline and complete a first-pass review."
      },
      {
        "kind": "paragraph",
        "text": "Let me know if you have any questions — I'm happy to walk through anything on this list. Thanks, and I appreciate your help getting this over the line.\n\nDes"
      }
    ]
  }
}
